<?php require_once 'config/database.php';require_once 'includes/auth.php';requireProfile($conn);$uid=(int)$_SESSION['user_id'];
function norm($s){$s=mb_strtolower(trim($s??''));$s=preg_replace('/[^\p{L}\p{N}\s]/u',' ',$s);return preg_replace('/\s+/u',' ',$s);}function sim($a,$b){$a=norm($a);$b=norm($b);if(!$a||!$b)return 0;if($a===$b)return 100;similar_text($a,$b,$p);return $p;}function overlap($a,$b){$a=array_unique(array_filter(explode(' ',norm($a)),fn($x)=>mb_strlen($x)>=3));$b=array_unique(array_filter(explode(' ',norm($b)),fn($x)=>mb_strlen($x)>=3));if(!$a||!$b)return 0;return count(array_intersect($a,$b))/count(array_unique(array_merge($a,$b)))*100;}
$source=(int)($_GET['source_id']??0);$lost=[];$found=[];$rs=$conn->query("SELECT id,user_id,category_id,location_id,item_name,description,incident_date FROM reports WHERE type='LOST' AND status='VERIFIED'");while($x=$rs->fetch_assoc())$lost[]=$x;$rs=$conn->query("SELECT id,user_id,category_id,location_id,item_name,description,incident_date FROM reports WHERE type='FOUND' AND status='VERIFIED'");while($x=$rs->fetch_assoc())$found[]=$x;$count=0;
foreach($lost as $l)foreach($found as $f){if($l['user_id']===$f['user_id'])continue;$score=0;$re=[];if($l['category_id']&&$l['category_id']===$f['category_id']){$score+=25;$re[]='Kategori sama';}if($l['location_id']&&$l['location_id']===$f['location_id']){$score+=20;$re[]='Lokasi sama';}$n=sim($l['item_name'],$f['item_name']);if($n>=80){$score+=30;$re[]='Nama sangat mirip';}elseif($n>=60){$score+=20;$re[]='Nama cukup mirip';}elseif($n>=40){$score+=10;$re[]='Nama memiliki kemiripan';}$d=overlap($l['description'],$f['description']);if($d>=50){$score+=15;$re[]='Ciri/deskripsi sangat mirip';}elseif($d>=25){$score+=10;$re[]='Ciri/deskripsi cukup mirip';}elseif($d>0){$score+=5;$re[]='Ada kesamaan deskripsi';}if($l['incident_date']&&$f['incident_date']){$days=abs((new DateTime($l['incident_date']))->diff(new DateTime($f['incident_date']))->days);if($days<=1){$score+=10;$re[]='Tanggal sangat dekat';}elseif($days<=3){$score+=7;$re[]='Tanggal cukup dekat';}elseif($days<=7){$score+=3;$re[]='Tanggal berdekatan';}}if($score<40)continue;$reason=implode(', ',$re);$st=$conn->prepare('SELECT id FROM matches WHERE lost_report_id=? AND found_report_id=? LIMIT 1');$st->bind_param('ii',$l['id'],$f['id']);$st->execute();$ex=$st->get_result()->fetch_assoc();$st->close();if($ex){$st=$conn->prepare('UPDATE matches SET score=?,matching_reason=? WHERE id=?');$st->bind_param('isi',$score,$reason,$ex['id']);$st->execute();$st->close();}else{$st=$conn->prepare('INSERT INTO matches(lost_report_id,found_report_id,score,matching_reason) VALUES(?,?,?,?)');$st->bind_param('iiis',$l['id'],$f['id'],$score,$reason);$st->execute();$st->close();}$count++;}
header('Location: matching.php?source_id='.$source.'&generated='.$count);exit;
